import { Component, Host, h, Element, Prop, Event, EventEmitter } from '@stencil/core';

type genericView = {
  getDOMNode: (props: any) => HTMLElement;
  dispose?: () => void;
  onRender?: () => void;
}

@Component({
  tag: 'hbr-generic-view',
  shadow: false,
})
export class HbrGenericView {
  genericView: genericView;

  @Element() host: HTMLHbrGenericViewElement;

  /** The view to render. Usually wraps a component from a view framework like React, Angular etc.*/
  @Prop() view: () => genericView;

  /** Set to true to emit hbr-disconnect / onHbrDisconnect event. */
  @Prop() emitDisconnect: boolean = false;

  @Prop() viewProps: { [key: string]: any };
  /** Emitted on component connected. */
  @Event({ eventName: "hbr-connect" }) hbrConnect: EventEmitter;
  /** Emitted on component loaded. */
  @Event({ eventName: "hbr-load" }) hbrLoad: EventEmitter;
  /** Emitted on component loaded. */
  @Event({ eventName: "hbr-render" }) hbrRender: EventEmitter;
  /** Emitted on component disconnected. */
  @Event({ eventName: "hbr-disconnect" }) hbrDisconnect: EventEmitter;

  connectedCallback() {
    this.hbrConnect.emit();
  }

  componentDidLoad() {
    this.hbrLoad.emit();

    try {
      if (this.host && typeof this.view === "function") {
        this.genericView = this.view();
        this.host.appendChild(this.genericView.getDOMNode(this.viewProps))
        if (this.genericView.onRender) this.genericView.onRender()
      }
    } catch (err) {
      console.error("Failed to render wrapped view", err)
    }
  }

  componentDidRender() {
    this.hbrRender.emit();

    try {
      if (this.genericView) {
        this.genericView.getDOMNode(this.viewProps)
      }
    } catch (err) {
      console.error("Failed to update wrapped view", err)
    }
  }

  disconnectedCallback() {
    if (this.emitDisconnect) {
      this.hbrDisconnect.emit();
    }

    try {
      if (this.genericView && this.genericView.dispose) {
        this.genericView.dispose()
      }
    } catch (err) {
      console.error("Failed to dispose wrapped view")
    }
  }

  render() {
    return <Host style={{ display: "contents" }}></Host>;
  }

}
